ornek: {
  baslik: "START'a basınca fan çalışmıyor: şemadan ölçüme",
  adimlar: [
    "Antet: sayfa 3/4 kumanda, kumanda 230 V AC, REV C. Cep dosyasındaki son revizyon da C; doğru çizimle çalışıyorsun.",
    "Tek hat (sayfa 1), kaynaktan yüke: ADP çıkışı → Q1 → KM1 → F2 termik → fan M1. Q1 kapalı, güç tarafında besleme var.",
    "Kumanda (sayfa 3): KM1 bobin yolu L → F4 → X1:1 → S0 (11-12, NC) → X1:2 → F2 95-96 → S1 (13-14, NO) → KM1 A1; A2 → N. S0 ve S1 kapakta, panoya X1 klemensleri üzerinden bağlı.",
    "Referansı N barası yap, sırayla ölç: F4 çıkışı 230 V, X1:1 230 V, X1:2 230 V (stop kontağı sağlam), F2'nin 95 ucu 230 V, 96 ucu 0 V.",
    "Gerilim 95'te var, 96'da yok: termiğin NC kontağı açık. Şemada F2 97-98'e bağlı H2 arıza lambasına bak: yanıyor. Termik atmış.",
    "Termiği resetle, START'a bas: KM1 çeker, fan döner. Ama asıl soru neden attığıdır; motor akımını pensle ölç, termik ayarıyla kıyasla (Ders 32)."
  ],
  sonuc: "Şema, ölçüm noktalarını sırayla verdi: gerilimin kaybolduğu iki nokta (95 ve 96) arızalı elemanı gösterdi. Enerjili ölçüm yetki, KKD ve CAT sınıfı uygun ölçü aleti ister (Ders 13)."
},
yokla: [
  { s: "Şemada SHEET 2/4 ve REV B yazıyor, panodaki cep dosyasında REV D var. Ne yaparsın?", c: "Elindeki çizim eski; pano tadilat görmüş olabilir. REV D çizimini bulup onunla çalışırsın, eksik sayfayla da karar vermezsin." },
  { s: "Bir kontaktörde 43-44 ve 61-62 kontakları var. Hangisi NO, hangisi NC?", c: "Son rakamları 3-4 olan 43-44 NO, 1-2 olan 61-62 NC'dir. İlk rakamlar kontağın sıra numarasıdır." },
  { s: "Şemada açık çizilmiş KM1 13-14 kontağını ölçtün, kapalı çıktı. Arıza mı?", c: "Şema enerjisiz hâli gösterir. KM1 o an çekiliyse 13-14'ün kapalı olması normaldir. Önce bobinin çekili olup olmadığına bakarsın." },
  { s: "Bir motorun enerjisini kesmeden önce tek hat şemasında neye bakarsın?", c: "Motoru besleyebilecek bütün kaynaklara: şebeke, jeneratör, UPS, varsa ikinci besleme. Hepsini kesip kilitledikten sonra gerilim yokluğunu doğrularsın." },
  { s: "Önceki derslerden: Kumanda devresinde 24 V DC var. Multimetreyi AC 200 V kademesinde tutup ölçtün, 0 V gördün. Sonuç ne?", c: "Ölçüm geçersiz; DC gerilimi AC kademede ölçemezsin. Kademeyi DC'ye alıp tekrar ölçersin (Ders 13)." },
  { s: "Önceki derslerden: ADP çıkışındaki şalterin S ayarı neden tali panodaki arızada açmamasını sağlar?", c: "S ayarı şalteri kısa bir süre (ör. 0,1 s) bekletir; alttaki otomat bu sürede arızayı keser, üstteki açmaz (Ders 29)." }
],
